#!/usr/bin/env bash
# The App Review demo account (docs/OPERATIONS.md → App Review demo account): creates
# or resets review@ryftapp.de and fills it with 60 days (scripts/seed_demo.py). The
# password comes from the in-cluster Vault (kv-operator/demo, generated by infra/vault;
# the only Vault, D207); it goes into App Store Connect, never into the repo.
#
#   kubectl --context ryft-prod-euc1 -n vault port-forward svc/vault-active 8200   # another terminal
#   export VAULT_CACERT=<the in-cluster Vault's CA> VAULT_TOKEN=<read on kv-operator/data/demo>
#   SUPABASE_URL=https://<ref>.supabase.co SUPABASE_ANON_KEY=sb_publishable_… SUPABASE_SECRET_KEY=sb_secret_… \
#   ADMIN_API_KEY=$(terraform -chdir=infra/vault output -raw admin_api_key) scripts/seed_demo.sh
#
# DEMO_PASSWORD in the environment skips Vault. Otherwise the vault CLI reads kv-operator/demo with
# VAULT_NAMESPACE removed for that call (Community Edition has none), and only through your
# port-forward: refused unless VAULT_ADDR is unset (the CLI's default is https://127.0.0.1:8200) or
# https loopback, and VAULT_SKIP_VERIFY is unset. RYFT_VAULT is gone with HCP Vault: unset, or `ce`
# (its old name for this path, changes nothing); any other value is refused.
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
: "${SUPABASE_URL:?set SUPABASE_URL}" "${SUPABASE_ANON_KEY:?set SUPABASE_ANON_KEY}"
: "${SUPABASE_SECRET_KEY:?set SUPABASE_SECRET_KEY (creates and resets the account)}"
if [ -z "${DEMO_PASSWORD:-}" ]; then
  case ${RYFT_VAULT:-ce} in
    ce) ;;
    *) echo "✗ seed_demo: RYFT_VAULT=\"$RYFT_VAULT\": HCP Vault is gone (D207) and the in-cluster Vault is the only one; unset RYFT_VAULT" >&2; exit 1 ;;
  esac
  # Only your port-forward, verified (as lib/admin.sh's ryft_vault_ok).
  loopback='^https://(127\.0\.0\.1|localhost|\[::1\])(:[0-9]{1,5})?/?$'
  if [ -n "${VAULT_ADDR:-}" ] && ! [[ $VAULT_ADDR =~ $loopback ]]; then
    echo "✗ seed_demo: VAULT_ADDR must be your port-forward (https://127.0.0.1:8200), not $VAULT_ADDR" >&2; exit 1
  fi
  [ -z "${VAULT_SKIP_VERIFY:-}" ] || { echo "✗ seed_demo: unset VAULT_SKIP_VERIFY (set VAULT_CACERT to the in-cluster Vault's CA instead)" >&2; exit 1; }
  DEMO_PASSWORD=$(unset VAULT_NAMESPACE; vault kv get -mount=kv-operator -field=password demo) \
    || { echo "✗ seed_demo: no DEMO_PASSWORD and the in-cluster Vault did not give it (the port-forward, VAULT_ADDR, VAULT_CACERT, VAULT_TOKEN; infra/vault applied?)" >&2; exit 1; }
fi
export DEMO_PASSWORD
exec python3 "$HERE/seed_demo.py"
